// Oracle-only chalk stub: colors disabled (upstream chalk auto-disables on
// non-TTY), so chalk.X(text) === text. Only the forms model-resolver.ts and
// cli/args.ts use are provided.
const identity = (text) => (typeof text === "string" ? text : String(text));
const chalk = {
  level: 0,
  yellow: identity,
  red: identity,
  dim: identity,
  green: identity,
  blue: identity,
  bold: identity,
};
export default chalk;
export const yellow = identity;
export const red = identity;
export const dim = identity;
